const MODE_OFF = 1;
const MODE_SUN_ONLY = 2;
const MODE_ESS_ONLY = 3;
const MODE_NIGHT = 4;
const MODE_ON = 5;
const MODE_MANUAL = 6;
const TARGET_AMPS_MIN = 7;
const TARGET_AMPS_NORMAL = 12;

const mode = msg.payload.mode;
const chargingPower = msg.payload.chargingPower;
const chargerStatus = msg.payload.chargerStatus;
const soc = msg.payload.soc
const minSoc = msg.payload.minSoc;
const batteryPower = msg.payload.batteryPower;
const targetAmpsMax = msg.payload.maxAmps || 18;
const hours = new Date().getHours();
const evening = (hours < 8) || (hours >= 22);

function powerToAmps(power) {
    return Math.min(targetAmpsMax, Math.round(power / 240));
}

function calcAmpsWhenDayOnly() {
    if (soc < minSoc + 5) {
        return 0;
    }
    let targetBatteryCharge = 0;
    if (soc > 95) {
        targetBatteryCharge = -2000;
    }
    const targetPower = chargingPower + batteryPower - targetBatteryCharge;
    return powerToAmps(targetPower);
}

// targetAmps < 7 -> turned off, 7..18 -> charges at this current
function generateOutput(targetAmps, chargingAmps, chargerStatus) {
    const result = [null, null];

    if (targetAmps == undefined || targetAmps == chargingAmps) return result;

    let newStartStop;
    let newCurrent;

    if (targetAmps < TARGET_AMPS_MIN) {
        // turn off
        if (chargingAmps > 0) {
            // stop
            newStartStop = 0;
            // set min current
            newCurrent = TARGET_AMPS_MIN;
        }
    } else {
        // status: Connected, Waiting for start
        if ((chargerStatus == 1 || chargerStatus == 6) && (targetAmps >= 8)) {
            // start
            newStartStop = 1;
            newCurrent = TARGET_AMPS_NORMAL;
        }

        // adjust current
        newCurrent = targetAmps;
    }

    if (newCurrent != undefined) {
        result[0] = { payload: { value: newCurrent } };
    }
    if (newStartStop != undefined) {
        result[1] = { payload: { value: newStartStop } };
    }

    return result;
}

let targetAmps = undefined;

if (mode >= MODE_OFF && mode <= MODE_ON) {
    if (mode == MODE_OFF) {
        targetAmps = 0;
        // on
    } else if (mode == MODE_ON) {
        targetAmps = TARGET_AMPS_NORMAL;
    } else {
        if (!evening) {
            targetAmps = calcAmpsWhenDayOnly();
        } else {
            if (mode == MODE_SUN_ONLY) {
                targetAmps = 0;
            } else if (mode == MODE_ESS_ONLY) {
                const eveningSocMargin = 2 * ((24 + 8 - hours) % 24);                
                if (soc > minSoc + eveningSocMargin) {
                    targetAmps = TARGET_AMPS_NORMAL;
                } else {
                    targetAmps = 0;
                }
            }  else if (mode == MODE_NIGHT) {
                targetAmps = TARGET_AMPS_NORMAL;
            }
        }
    }
}

return generateOutput(targetAmps, powerToAmps(chargingPower), chargerStatus);

