function createNonce() {
	var s = '', length = 32;
	do {
		s += Math.random().toString(36).substr(2);
	} while (s.length < length);
	s = s.substr(0, length);
	return s;
}

function getHmacInput(time, nonce, body) {
  return apiKey + "\0" + 
    time + "\0" + 
    nonce + "\0" + 
    "\0" + 
    organizationId + "\0" + 
    "\0" + 
    method + "\0" + 
    path + "\0" + 
    queryString
    + 
    (body ? "\0" + JSON.stringify(body) : "");
};

msg.headers["X-Auth"] = msg.apiKey + ":" + msg.payload;
msg.payload = msg.body;
return msg;
